            freq_divbyeven #(.NUM_DIV(DIV_VALUE)) uut (
                .clk(clk),
                .rst_n(rst_n),
                .clk_div(clk_div[i])
            );

            freq_divbyeven_checker #(.NUM_DIV(DIV_VALUE)) checker (
                .clk(clk),
                .rst_n(rst_n),
                .clk_div(clk_div[i]),
                .error(error[i])
            );
        end
    endgenerate

    initial begin
        clk = 0;
        rst_n = 0;
        #12 rst_n = 1;
        #1200;

        fail_count = 0;
        for (j = 0; j < 16; j = j + 1) begin
