module freq_divbyeven_checker #(
    parameter NUM_DIV = 6
)(
    input clk,
    input rst_n,
    input clk_div,
    output reg error
);
    reg [3:0] cnt;
    reg expected_clk_div;
    integer check_count;

    initial begin
        error = 0;
        check_count = 0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 4'd0;
            expected_clk_div <= 1'b0;
        end
        else if (cnt < NUM_DIV / 2 - 1) begin
            cnt <= cnt + 1'b1;
            expected_clk_div <= expected_clk_div;
        end
        else begin
            cnt <= 4'd0;
            expected_clk_div <= ~expected_clk_div;
        end
    end

    always @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            error <= 0;
            check_count <= 0;
        end
        else begin
            check_count <= check_count + 1;
            if (clk_div !== expected_clk_div) begin
                error <= 1;
                $display("Failed NUM_DIV=%0d at check %0d: clk_div=%0d (expected %0d)",
                         NUM_DIV, check_count, clk_div, expected_clk_div);
            end
        end
    end
endmodule

