module square_wave(
    input clk,                     
    input [7:0] freq,           
    output reg wave_out          
);

reg [7:0] count;                

initial begin
    wave_out = 0;  
    count = 0;     
end

always @(posedge clk) begin
    if(count == freq - 1 ) begin      
        count <= 0;
        wave_out <=  ~wave_out ;            

    end else begin
        count <= count + 1;        
    end
end

endmodule
